// The replay view client against the gateway itself (root backlog 0993, runtime 0854).
// Run after `npm run build`: node scripts/check_replay_view.mjs
//
// Fixtures (`fixtures/replay_view/<case>/`, regenerated by regen_replay_view_fixtures.py against
// a real AbstractGateway 0.17.0 / AbstractRuntime 0.15.0): every one of the runtime's conformance
// cases appended to the gateway's stores one record at a time; `stream.sse` is what
// `GET /view/stream` sent (a `view`, then one `delta` per fold), `steps.json` the SHA-256 of
// `GET /view` after each record, `final_view.json` the last GET body (= the case's expected view).
//
// Checked here, for every case and every step:
// - the stream parsed by `SseParser` in arbitrary chunks and folded with `ReplayViewFold`
//   serializes to EXACTLY the bytes of the gateway's GET at that step;
// - a skipped delta is caught at its step (red), and so is a stale frame re-applied without the
//   fold's guard; the guard drops a repeated frame (`duplicate`) and an older one (`stale`);
// - a reconnect frame (`Last-Event-ID` = the previous token) brings the held view to the GET;
// - `createReplayViewTransport` over a fetch: 200 / 304 / route missing / run missing / stream.
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { readFileSync, readdirSync, existsSync } from "node:fs";
import {
  applyDelta,
  parseCursorToken,
  SseParser,
  ReplayViewFold,
  createReplayViewTransport,
  ReplayViewUnavailableError,
  REPLAY_VIEW_VERSION,
} from "../dist/replay_view.js";
import * as api from "../dist/index.js";

let checks = 0;
const ok = () => { checks += 1; };
const dir = new URL("./fixtures/replay_view/", import.meta.url);
const index = JSON.parse(readFileSync(new URL("index.json", dir), "utf8"));
const sha = (text) => createHash("sha256").update(Buffer.from(text, "utf8")).digest("hex");
const bytesOf = (view) => JSON.stringify(view);

// ---- the fixture set is the runtime's whole conformance suite -------------------------------
const cases = readdirSync(dir, { withFileTypes: true }).filter((d) => d.isDirectory()).map((d) => d.name).sort();
assert.equal(cases.length, 15, "fixtures: the 15 conformance cases of AbstractRuntime 0.15.0");
assert.deepEqual(cases, index.cases.map((c) => c.name).sort(), "fixtures: index.json lists every case");
assert.equal(index.versions.abstractgateway, "0.17.0");
assert.equal(index.versions.abstractruntime, "0.15.0");
ok();

/** Parse a stream in pseudo-random chunk sizes (split CRLF, split UTF-8 is the transport's job). */
function framesOf(text, seed = 7) {
  const parser = new SseParser();
  const out = [];
  let i = 0;
  let s = seed;
  while (i < text.length) {
    s = (s * 1103515245 + 12345) % 2147483648;
    const n = 1 + (s % 97);
    out.push(...parser.push(text.slice(i, i + n)));
    i += n;
  }
  return out;
}

/** Fold `frames` step by step; the step boundaries come from steps.json (`frames` per step). */
function foldSteps(frames, steps, { skip = -1, fold = new ReplayViewFold() } = {}) {
  const shas = [];
  let f = 0;
  for (let step = 0; step < steps.length; step += 1) {
    for (let n = 0; n < steps[step].frames; n += 1, f += 1) if (f !== skip) fold.apply(frames[f]);
    shas.push(fold.view ? sha(bytesOf(fold.view)) : null);
  }
  return { shas, fold };
}

let totalSteps = 0;
let skipsCaught = 0;
let skipsTried = 0;
let reconnects = 0;
for (const name of cases) {
  const caseDir = new URL(`${name}/`, dir);
  const streamText = readFileSync(new URL("stream.sse", caseDir), "utf8");
  const steps = JSON.parse(readFileSync(new URL("steps.json", caseDir), "utf8"));
  const finalBody = readFileSync(new URL("final_view.json", caseDir), "utf8");
  const frames = framesOf(streamText, name.length);
  assert.equal(frames[0].event, "view", `${name}: the stream starts with the whole view`);
  assert.equal(frames.length, 1 + steps.slice(1).reduce((n, s) => n + s.frames, 0), `${name}: one frame per fold`);
  assert.ok(frames.slice(1).every((fr) => fr.event === "delta" && fr.id), `${name}: every later frame is an identified delta`);

  // 1. Folded == GET at every step, byte for byte.
  const { shas, fold } = foldSteps(frames, steps);
  steps.forEach((s, i) => assert.equal(shas[i], s.sha256, `${name}: step ${i} (${s.record || "initial"}) folded view != GET /view`));
  assert.equal(bytesOf(fold.view), finalBody, `${name}: the folded view is the final GET body, byte for byte`);
  assert.equal(fold.view.version, REPLAY_VIEW_VERSION);
  assert.equal(fold.lastEventId, steps.at(-1).etag.replace(/"/g, ""), `${name}: Last-Event-ID is the last token`);
  totalSteps += steps.length;
  ok();

  // 2. A skipped delta is caught at its step.
  for (let f = 1; f < frames.length; f += 1) {
    skipsTried += 1;
    const skipped = foldSteps(frames, steps, { skip: f }).shas;
    if (skipped.some((h, i) => h !== steps[i].sha256)) skipsCaught += 1;
  }

  // 3. A repeated frame is a no-op; an older frame after a newer one is refused.
  for (let f = 1; f + 1 < frames.length; f += 1) {
    const g = new ReplayViewFold();
    for (let i = 0; i <= f; i += 1) g.apply(frames[i]);
    const before = bytesOf(g.view);
    assert.equal(g.apply(frames[f]), "duplicate", `${name}: frame ${f} again is a duplicate`);
    assert.equal(bytesOf(g.view), before);
    g.apply(frames[f + 1]);
    const newer = bytesOf(g.view);
    const outcome = g.apply(frames[f]);
    assert.equal(outcome, "stale", `${name}: frame ${f} after frame ${f + 1} is stale`);
    assert.equal(bytesOf(g.view), newer, `${name}: a stale frame never moves the view back`);
    // Without the guard the same stale frame moves the view back: the guard is load-bearing.
    const unguarded = applyDelta(JSON.parse(newer), JSON.parse(frames[f].data));
    assert.notEqual(bytesOf(unguarded), newer, `${name}: re-applying frame ${f} unguarded regresses the view`);
  }
  ok();

  // 4. Reconnect: the frame a stream sends for Last-Event-ID = the previous step's token.
  let f = 0;
  const views = [];
  const g = new ReplayViewFold();
  for (let step = 0; step < steps.length; step += 1) {
    for (let n = 0; n < steps[step].frames; n += 1, f += 1) g.apply(frames[f]);
    views.push(JSON.stringify(g.view));
  }
  steps.forEach((s, i) => {
    if (!s.reconnect) return;
    const held = new ReplayViewFold();
    held.adopt(JSON.parse(views[i - 1]), steps[i - 1].etag);
    const parser = new SseParser();
    const got = s.reconnect.flatMap((text) => parser.push(text));
    assert.equal(got.length, 1, `${name}: a reconnect sends one frame`);
    const outcome = held.apply(got[0]);
    assert.ok(outcome === "delta" || outcome === "view", `${name}: reconnect frame applied (${outcome})`);
    assert.equal(sha(bytesOf(held.view)), s.sha256, `${name}: step ${i} after a reconnect != GET /view`);
    reconnects += 1;
  });
  ok();
}
assert.equal(skipsCaught, skipsTried, `every skipped delta is caught at its step (${skipsCaught}/${skipsTried})`);
assert.ok(totalSteps > 250 && reconnects > 60, `coverage: ${totalSteps} steps, ${reconnects} reconnects`);
ok();

// ---- applyDelta unit rules (python parity) ---------------------------------------------------
{
  const v = applyDelta(null, { status: "running", messages: [{ id: "b", order: ["t", "r", 10] }, { id: "a", order: ["t", "r", 9] }] });
  assert.deepEqual(v.messages.map((m) => m.id), ["a", "b"], "ints compare as numbers (zero-padded), not as text");
  assert.deepEqual(v.runs, [], "an absent list is an empty list");
  const w = applyDelta(v, { messages: [{ id: "z", order: ["t"] }] });
  assert.deepEqual(w.messages.map((m) => m.id), ["z", "a", "b"], "a prefix sorts first (a parent before its children)");
  assert.equal(w.status, "running", "an absent scalar is kept");
  const x = applyDelta(w, { interaction: null });
  assert.ok("interaction" in x && x.interaction === null, "a present null scalar replaces");
  assert.equal(v.messages.length, 2, "the input view is not modified");
  const y = applyDelta({ runs: [{ run_id: "r1", order: [-1] }, { run_id: "r2", order: [2] }] }, { runs: [{ run_id: "r3", order: [-2] }] });
  assert.deepEqual(y.runs.map((r) => r.run_id), ["r1", "r3", "r2"], "negative ints format like python 012d (\"-00000000001\" < \"-00000000002\" < \"000000000002\"), as abstractruntime apply_delta orders them");
  ok();
}

// ---- cursor tokens ---------------------------------------------------------------------------
assert.deepEqual(parseCursorToken('W/"73c7888f:4.a4a4a4a4:2~3515304d7d"'), { "73c7888f": 4, a4a4a4a4: 2 });
assert.equal(parseCursorToken("not-a-token"), null);
assert.equal(parseCursorToken("abc:-1"), null);
assert.equal(parseCursorToken(""), null);
ok();

// ---- SSE parser edge cases -------------------------------------------------------------------
{
  const p = new SseParser();
  const got = [
    ...p.push(": keep-alive\r"),
    ...p.push("\n\r\nid: t1\r\nevent: delta\r"),
    ...p.push("\ndata: {\"a\":\ndata: 1}\r\n\r\n"),
    ...p.push("event: done\ndata: {}\n\nevent: delta\ndata: {\"unterminated\":true}"),
  ];
  assert.deepEqual(got, [{ event: "delta", data: '{"a":\n1}', id: "t1" }, { event: "done", data: "{}" }], "CRLF split across chunks, comments, multi-line data");
  assert.equal(p.lastEventId, "t1", "the id persists for Last-Event-ID");
  ok();
}

// ---- the fold refuses a delta without a view -------------------------------------------------
assert.throws(() => new ReplayViewFold().apply({ event: "delta", data: "{}" }), /before any view/);
ok();

// ---- createReplayViewTransport over a fetch --------------------------------------------------
{
  const final = readFileSync(new URL("g_ask_user/final_view.json", dir), "utf8");
  const stream = readFileSync(new URL("g_ask_user/stream.sse", dir), "utf8");
  const calls = [];
  const enc = new TextEncoder();
  const fetchFor = (handler) => async (path, init) => { calls.push({ path, headers: { ...init.headers } }); return handler(path, init); };
  const ok200 = new Response(final, { status: 200, headers: { ETag: '"tok-1"', "Content-Type": "application/json" } });
  let t = createReplayViewTransport({ fetch: fetchFor(() => ok200) });
  let read = await t.getView("run/1");
  assert.equal(read.notModified, false);
  assert.equal(read.etag, '"tok-1"');
  assert.equal(read.bytes, Buffer.byteLength(final));
  assert.equal(calls[0].path, "runs/run%2F1/view", "the run id is encoded; the path is relative to the gateway API");
  t = createReplayViewTransport({ fetch: fetchFor(() => new Response(null, { status: 304, headers: { ETag: '"tok-1"' } })) });
  read = await t.getView("r", { ifNoneMatch: '"tok-1"' });
  assert.equal(read.notModified, true);
  assert.equal(calls.at(-1).headers["If-None-Match"], '"tok-1"');
  t = createReplayViewTransport({ fetch: fetchFor(() => new Response('{"detail":"Not Found"}', { status: 404 })) });
  await assert.rejects(t.getView("r"), (e) => e instanceof ReplayViewUnavailableError && /0\.17\.0/.test(e.message), "an unmatched route = no replay view");
  t = createReplayViewTransport({ fetch: fetchFor(() => new Response("{\"detail\":\"Run 'r' not found\"}", { status: 404 })) });
  await assert.rejects(t.getView("r"), (e) => !(e instanceof ReplayViewUnavailableError) && e.status === 404 && /not found/.test(e.detail), "a missing run is not a missing route");
  t = createReplayViewTransport({ fetch: fetchFor(() => new Response('{"version":"replay_view_v2"}', { status: 200 })) });
  await assert.rejects(t.getView("r"), /Unsupported replay view version/);
  // Stream: bytes in odd chunks (a UTF-8 sequence split across two), Last-Event-ID sent, done ends it.
  const body = enc.encode(stream + "event: done\ndata: {}\n\n");
  t = createReplayViewTransport({
    fetch: fetchFor(() => new Response(new ReadableStream({
      start(controller) { for (let i = 0; i < body.length; i += 13) controller.enqueue(body.slice(i, i + 13)); controller.close(); },
    }), { status: 200, headers: { "Content-Type": "text/event-stream" } })),
  });
  const seen = [];
  let opened = 0;
  const res = await t.streamView("r", { lastEventId: "tok-0", signal: new AbortController().signal, onOpen: () => { opened += 1; }, onFrame: (fr) => seen.push(fr) });
  assert.equal(calls.at(-1).headers["Last-Event-ID"], "tok-0");
  assert.equal(calls.at(-1).path, "runs/r/view/stream");
  assert.equal(opened, 1);
  assert.equal(res.bytes, body.length);
  assert.equal(seen.at(-1).event, "done");
  const g = new ReplayViewFold();
  for (const fr of seen) g.apply(fr);
  assert.equal(JSON.stringify(g.view), final, "the transport's frames fold to the GET body");
  ok();
}

// ---- public API ------------------------------------------------------------------------------
for (const name of ["applyDelta", "parseCursorToken", "SseParser", "ReplayViewFold", "createReplayViewTransport", "ReplayViewUnavailableError"]) assert.equal(typeof api[name], "function", `index exports ${name}`);
ok();
assert.ok(existsSync(new URL("../../regen_replay_view_fixtures.py", dir)), "the fixture generator ships with the fixtures");

console.log(`check_replay_view: ${checks} groups OK (${cases.length} cases, ${totalSteps} steps byte-equal to GET /view, ${skipsCaught}/${skipsTried} skipped deltas caught, ${reconnects} reconnects)`);
